export const BODY: string = "\n<p>تصویر پر متن صرف تب مفید ہوتا ہے جب لوگ اسے پڑھ سکیں۔ روشن آسمان میں غائب ہونے والی سرخی یا تاریک سائے میں ملنے والا کیپشن اپنے واحد کام میں ناکام ہوتا ہے۔</p>\n<p>کنٹراسٹ وہی ہے جو متن کو پڑھنے کے قابل بناتا ہے۔ یہ حروف اور ان کے پیچھے پس منظر کے درمیان چمک کا فرق ہے، اور اسے تصویر میں، متن میں، یا دونوں میں ٹھیک کیا جا سکتا ہے۔</p>\n<p>یہ مضمون بتاتا ہے کہ وہ کنٹراسٹ کیسے بنائیں۔ اس میں تاریک کرنا، اوورلے، پینل، رنگ انتخاب، اور ٹیسٹ عادتیں شامل ہیں جو ناقابل پڑھ متن کو شائع ہونے سے پہلے پکڑتی ہیں۔</p>\n<h2 id=\"why-contrast-matters\">کنٹراسٹ فونٹ سے زیادہ کیوں اہمیت رکھتا ہے</h2>\n<p>خوبصورت فونٹ جسے کوئی پڑھ نہ سکے ناکام ڈیزائن ہے۔ تصویر پر متن کا پہلا کام پڑھا جانا ہے، اور کنٹراسٹ طے کرتا ہے کہ وہ کام ہوتا ہے یا نہیں۔</p>\n<p>زیادہ تر تصاویر فون پر، فیڈ میں، چھوٹے سائز پر دیکھی جاتی ہیں۔ کمپیوٹر پر پورے سائز پر صاف متن فیڈ پیش نظارہ میں ناقابل پڑھ ہو سکتا ہے، جہاں تصویر بہت چھوٹی دکھائی جاتی ہے۔</p>\n<p>کنٹراسٹ بھروسے کو بھی متاثر کرتا ہے۔ کرکرا، صاف متن والی پوسٹ پیشہ ورانہ لگتی ہے، جبکہ مدھم، کم کنٹراسٹ متن والی پوسٹ لاپرواہ لگتی ہے، چاہے اس کے نیچے تصویر کتنی ہی اچھی ہو۔</p>\n<p>فونٹ کی فکر سے پہلے کنٹراسٹ ٹھیک کریں۔ اگر الفاظ پڑھنا مشکل ہوں تو کوئی ٹائپ فیس انہیں نہیں بچائے گا، اور مضبوط کنٹراسٹ والا سادہ فونٹ فینسی فونٹ کو ہراتا ہے۔</p>\n<h2 id=\"text-vs-background\">متن بمقابلہ پس منظر: بنیادی تعلق</h2>\n<p>پڑھنے کی اہلیت متن کی چمک اور پس منظر کی چمک کے درمیان فرق سے آتی ہے۔ تاریک پس منظر پر سفید متن کا فرق بڑا ہوتا ہے، اور ہلکے پس منظر پر سیاہ متن کا بھی۔</p>\n<p>مسئلہ تب آتا ہے جب پس منظر ایک ہی سطر کے پیچھے بدلتا ہے۔ تاریک سائے پر شروع اور روشن آسمان پر ختم ہونے والا کیپشن ایک سرے پر پڑھنے کے قابل اور دوسرے پر پوشیدہ ہو گا۔</p>\n<p>پوری سطر پر کنٹراسٹ چیک کریں، صرف ایک نقطے پر نہیں۔ ہر لفظ پڑھنے کے قابل ہونا چاہیے، اور پس منظر سطر کے نیچے نہیں بدلنا چاہیے۔</p>\n<p>جب پس منظر بدلتا ہو تو پس منظر ٹھیک کریں، متن نہیں۔ تصویر تاریک کریں، اوورلے بڑھائیں، یا الفاظ کے پیچھے پینل رکھیں تاکہ مستقل زون بنے۔</p>\n<h2 id=\"choosing-text-colour\">کنٹراسٹ کے لیے متن رنگ چننا</h2>\n<p>سفید تصاویر پر متن کے لیے محفوظ ترین رنگ ہے، کیونکہ زیادہ تر تصاویر میں اس کے پڑھنے کے لیے کافی تاریک علاقے ہوتے ہیں، اور تاریک خاکہ اسے روشن علاقوں پر بھی کام کراتا ہے۔</p>\n<p>سیاہ ہلکی، ہوائی تصاویر پر اچھی طرح کام کرتا ہے جیسے ساحل، برف کے منظر، اور سفید دیواریں۔ یہ تاریک تصاویر پر ناکام ہوتا ہے، جہاں یہ سائے میں غائب ہو جاتا ہے۔</p>\n<p>پیلا یا سیان جیسے روشن رنگ مختصر سرخیوں کے لیے کام کر سکتے ہیں، مگر وہ لمبے کیپشن میں پڑھنا مشکل ہوتے ہیں۔ مضبوط رنگ چند الفاظ کے لیے محفوظ رکھیں۔</p>\n<p>مرکزی متن کے لیے ایک رنگ اور زور کے لیے زیادہ سے زیادہ دوسرا رنگ استعمال کریں۔ بہت سے رنگ ملانا افراتفری لگتا ہے، جبکہ مستقل جوڑا ڈیزائن کو صاف اور پڑھنے کے قابل رکھتا ہے۔</p>\n<h2 id=\"darkening-photo\">متن کے پیچھے تصویر تاریک کرنا</h2>\n<p>پوری تصویر تاریک کرنا سفید متن کو پڑھنے کے قابل بنانے کا سب سے آسان طریقہ ہے۔ بیس سے تیس فیصد چمک کمی تاریک زون بناتی ہے جس پر سفید حروف کھڑے ہوتے ہیں۔</p>\n<p>متن بڑھانے سے پہلے تصویر تاریک کرنے کے لیے <a href=\"/ur/tasveer-ki-brightness-badlein/\">Image Brightness Editor</a> استعمال کریں۔ تاریک تصویر حروف کو تصویر کو مکمل چھپائے بغیر صاف پس منظر دیتی ہے۔</p>\n<p>تاریک کرنے کے بعد تصویر چیک کریں۔ یہ پھر بھی وہی تصویر پہچانی جانی چاہیے، صرف مزاجی، موضوع نظر آتا ہو اور متن صاف پڑھنے کے قابل ہو۔</p>\n<p>روشن رہنے والی تصویر کے لیے صرف متن کے پیچھے والا علاقہ تاریک کریں۔ مقامی تاریک کرنا، یا اوورلے، باقی تصویر کو روشن رکھتا ہے جبکہ متن زون تاریک رہتا ہے۔</p>\n<h2 id=\"lightening-photo\">تاریک متن کے پیچھے تصویر ہلکی کرنا</h2>\n<p>ہلکا کرنا الٹا اسی طرح کام کرتا ہے۔ سیاہ متن کے پیچھے چمک بڑھانے سے ہلکا زون بنتا ہے جس کے خلاف تاریک حروف نمایاں ہوتے ہیں۔</p>\n<p>یہ روشن، ہوائی تصاویر کے لیے موزوں ہے جہاں متن ہلکا اور صاف محسوس ہونا چاہیے۔ مزید روشن کی گئی سفید دیوار یا ہلکا آسمان سیاہ متن کو کامل پس منظر دیتا ہے۔</p>\n<p>ہلکا کرتے وقت ہائی لائٹس دیکھیں۔ پہلے سے روشن آسمان خالص سفید میں پھٹ سکتا ہے، جو متن کے پیچھے ٹھیک ہے مگر تصویر میں کہیں اور عجیب لگتا ہے۔</p>\n<p>زیادہ تر تصاویر کے لیے سفید متن کے لیے تاریک کرنا محفوظ انتخاب ہے۔ ہلکی تصاویر تاریک تصاویر سے کم عام ہوتی ہیں، اور تاریک تصویر پر سفید متن کلاسک ترکیب ہے۔</p>\n<h2 id=\"overlays-and-panels\">اوورلے اور پس منظر پینل</h2>\n<p>اوورلے پوری تصویر پر رکھی گئی نیم شفاف تہہ ہوتی ہے۔ تاریک اوورلے سفید متن کو ہر جگہ پڑھنے کے قابل بناتا ہے، جبکہ تصویر پھر بھی اس سے نظر آتی ہے۔</p>\n<p>پینل اسی خیال کا چھوٹا ورژن ہے: صرف متن کے پیچھے رکھا گیا نیم شفاف ڈبہ۔ تاریک پینل سفید متن کو پڑھنے کے قابل بناتا ہے، اور ہلکا پینل سیاہ متن کے لیے وہی کرتا ہے۔</p>\n<p>پینل سب سے قابل اعتماد پڑھنے کی اہلیت حل ہیں، کیونکہ وہ مستقل پس منظر بناتے ہیں جو تصویر نہیں دے سکتی۔ وہ کسی بھی تصویر پر کام کرتے ہیں، چاہے وہ کتنی ہی مصروف ہو۔</p>\n<p>تبادلہ کوریج ہے۔ پینل تصویر کا حصہ چھپاتا ہے، اس لیے اسے جتنا متن اجازت دے اتنا چھوٹا رکھیں اور اسے کم اہم علاقے پر رکھیں۔</p>\n<h2 id=\"contrast-for-headlines\">سرخیوں کے لیے کنٹراسٹ</h2>\n<p>سرخیوں کو مضبوط ترین کنٹراسٹ چاہیے ہوتا ہے، کیونکہ وہ پہلی چیز ہوتی ہیں جنہیں آنکھ تلاش کرتی ہے۔ پڑھنے میں مشکل سرخی دیکھنے والے کو پوری تصویر چھوڑنے پر مجبور کرتی ہے۔</p>\n<p>مضبوط رنگ فرق کے ساتھ بڑا، بولڈ متن استعمال کریں۔ تاریک تصویر پر سفید بولڈ حروف، یا ہلکی تصویر پر سیاہ بولڈ حروف، دو قابل اعتماد ترکیبیں ہیں۔</p>\n<p>جب پس منظر بدلتا ہو تو سرخی میں خاکہ یا سایہ بڑھائیں۔ اثر ہر حرف کے گرد مقامی کنٹراسٹ زون بناتا ہے، جو سرخی کو پڑھنے کے قابل رکھتا ہے۔</p>\n<p>سرخی کو فیڈ سائز پر ٹیسٹ کریں۔ پورے سائز پر صاف سرخی چھوٹے پیش نظارہ میں ناقابل پڑھ ہو سکتی ہے، جہاں تصویر بہت چھوٹی دکھائی جاتی ہے۔</p>\n<h2 id=\"contrast-for-captions\">کیپشن اور چھوٹے متن کے لیے کنٹراسٹ</h2>\n<p>کیپشن اور چھوٹے متن کو سرخیوں سے بھی زیادہ احتیاط چاہیے ہوتی ہے، کیونکہ چھوٹے حروف پڑھنا مشکل ہوتے ہیں۔ کمزور کنٹراسٹ والا کیپشن فیڈ پیش نظارہ میں پوشیدہ ہوتا ہے۔</p>\n<p>چھوٹے متن کے پیچھے پینل استعمال کریں۔ مصروف تصویر پر کیپشن کو وہ مستقل پس منظر چاہیے ہوتا ہے جو صرف پینل دے سکتا ہے، کیونکہ صرف خاکہ کافی نہ ہو۔</p>\n<p>کیپشن مختصر رکھیں۔ مضبوط کنٹراسٹ والے چند الفاظ کمزور کنٹراسٹ والے لمبے جملے سے کہیں بہتر کام کرتے ہیں، جسے ویسے بھی کوئی نہیں پڑھے گا۔</p>\n<p>اگر کنٹراسٹ ٹھیک نہ ہو سکے تو سائز بڑھائیں۔ بڑے حروف اسی کنٹراسٹ سطح پر پڑھنا آسان ہوتے ہیں، اس لیے سائز بڑھانا کیپشن کو بچا سکتا ہے جو ناکام ہو رہا تھا۔</p>\n<h2 id=\"testing-readability\">شائع کرنے سے پہلے پڑھنے کی اہلیت ٹیسٹ کرنا</h2>\n<p>متن کو فون پر، فیڈ میں، اس سائز پر ٹیسٹ کریں جس پر یہ دکھایا جائے گا۔ تصویر ایکسپورٹ کریں، اسے اپنے فون پر کھولیں، اور چیک کریں کہ الفاظ بغیر زوم کے پڑھنے کے قابل ہیں یا نہیں۔</p>\n<p>تصویر کو مختلف روشنی میں بھی چیک کریں۔ روشن سورج کی روشنی میں فون اسکرین مدھم متن کو دھو دیتی ہے، اس لیے اندر پڑھنے کے قابل کیپشن باہر ناکام ہو سکتا ہے۔</p>\n<p>کسی اور سے اسے پڑھنے کو کہیں۔ تازہ آنکھیں ناقابل پڑھ متن کو اس شخص سے کہیں تیزی سے دیکھتی ہیں جس نے اسے بنایا، کیونکہ بنانے والا پہلے سے جانتا ہے کہ الفاظ کیا ہیں۔</p>\n<p>تصویر کو آنکھیں سکیڑ کر دیکھیں۔ اگر متن سکیڑنے پر بھی نظر آئے تو کنٹراسٹ کافی مضبوط ہے۔ اگر یہ غائب ہو جائے تو کنٹراسٹ کو کام چاہیے ہوتا ہے۔</p>\n<h2 id=\"contrast-for-social\">سوشل میڈیا متن کے لیے کنٹراسٹ</h2>\n<p>سوشل فیڈ بھیڑ بھری اور تیز ہوتی ہیں، اور متن ایک نظر میں پڑھنے کے قابل ہونا چاہیے۔ کمزور کنٹراسٹ والی پوسٹ اسکرول ہو جاتی ہے، جبکہ مضبوط کنٹراسٹ والی پوسٹ رکتی ہے۔</p>\n<p>سوشل متن کو بڑا اور زیادہ کنٹراسٹ رکھیں۔ سرخیوں کو حد کے اوپر کے قریب سائز چاہیے ہوتا ہے، اس کے پیچھے تصویر کے خلاف مضبوط رنگ فرق کے ساتھ۔</p>\n<p>یاد رکھیں کہ سوشل پلیٹفارم آپ کی تصاویر کو کمپریس کرتے ہیں۔ مدھم کیپشن کمپریشن کے بعد پوشیدہ ہو سکتا ہے، اس لیے متن کو پوسٹ کی ڈاؤن لوڈ شدہ کاپی پر ٹیسٹ کریں۔</p>\n<p>سوچیں کہ کیا متن تصویر پر ہونا ہی چاہیے۔ کیپشن میں الفاظ والی صاف تصویر ناقابل پڑھ متن والی نشان زد تصویر سے بہتر کارکردگی دکھا سکتی ہے۔</p>\n<h2 id=\"contrast-for-slides\">سلائیڈ اور پریزنٹیشن کے لیے کنٹراسٹ</h2>\n<p>سلائیڈ دور سے دیکھی جاتی ہیں، اس لیے متن کو بہت مضبوط کنٹراسٹ چاہیے ہوتا ہے۔ لیپ ٹاپ پر پڑھنے کے قابل سرخی کمرے کے پیچھے سے پوشیدہ ہو سکتی ہے۔</p>\n<p>سلائیڈ متن کے پیچھے تصویر کو فراخی سے تاریک کریں۔ تیس فیصد یا اس سے زیادہ چمک کمی سفید متن کو بڑی پروجیکشن اسکرین پر بھی صاف پس منظر دیتی ہے۔</p>\n<p>سلائیڈ کے لیے بڑا، بولڈ متن استعمال کریں۔ سرخی پچھلی قطار سے پڑھنے کے قابل ہونی چاہیے، جس کا مطلب سوشل پوسٹ کی ضرورت سے بڑے حروف اور مضبوط کنٹراسٹ ہے۔</p>\n<p>اگر ہو سکے تو سلائیڈ کو اصل پروجیکٹر پر ٹیسٹ کریں۔ پروجیکٹر رنگ دھوتے ہیں اور کنٹراسٹ کم کرتے ہیں، اس لیے اسکرین پر ٹھیک لگنے والی سلائیڈ کمرے میں ناکام ہو سکتی ہے۔</p>\n<h2 id=\"accessibility\">رسائی: کنٹراسٹ جسے سب پڑھ سکیں</h2>\n<p>اچھا کنٹراسٹ سب کی مدد کرتا ہے، مگر یہ کم نظر والے لوگوں کے لیے سب سے زیادہ اہمیت رکھتا ہے۔ زیادہ کنٹراسٹ، بڑا سائز، اور سادہ پس منظر متن کو کہیں زیادہ لوگوں کے لیے پڑھنے کے قابل بناتے ہیں۔</p>\n<p>معنی پہنچانے کے لیے صرف رنگ پر انحصار نہ کریں۔ سرخ لفظ اور سبز لفظ رنگ اندھے دیکھنے والے کو ایک جیسے لگ سکتے ہیں، اس لیے سائز یا وزن بھی استعمال کریں۔</p>\n<p>متن مختصر اور زبان سادہ رکھیں۔ سادہ الفاظ میں صاف کیپشن جارگن سے بھری چالاک کیپشن سے زیادہ قارئین تک پہنچتا ہے۔</p>\n<p>جب آپ تصویر شیئر کریں تو alt متن بڑھائیں۔ alt متن تصویر بیان کرتا ہے اور کیپشن دہراتا ہے، جو اسکرین ریڈر استعمال کرنے والوں کی مدد کرتا ہے۔</p>\n<h2 id=\"common-mistakes\">عام کنٹراسٹ غلطیاں</h2>\n<p>سب سے عام غلطی روشن تصویر پر سفید متن بغیر خاکہ، سایہ، یا پینل کے ہے۔ حروف آسمان میں غائب ہو جاتے ہیں، اور دیکھنے والا صرف تصویر دیکھتا ہے۔</p>\n<p>دوسری غلطی چہرے یا مصروف نمونے پر متن رکھنا ہے۔ آنکھ حروف کو نیچے کی بناوٹ سے الگ نہیں کر سکتی، اور الفاظ پیروی کرنا مشکل ہو جاتے ہیں۔</p>\n<p>لوگ بہت سے رنگ بھی استعمال کرتے ہیں۔ ایک تصویر پر تین یا چار متن رنگ افراتفری لگتے ہیں، جبکہ مضبوط کنٹراسٹ والا ایک مستقل رنگ ڈیزائن کو صاف رکھتا ہے۔</p>\n<p>آخر میں، متن وہاں نہ رکھیں جہاں پلیٹفارم اسے کراپ کرے گا۔ سوشل ایپ مختلف اسکرین کے لیے تصاویر کے کنارے تراشتی ہیں، اس لیے اہم الفاظ کو کناروں سے اچھی طرح اندر رکھیں۔</p>\n<h2 id=\"contrast-and-filters\">کنٹراسٹ، فلٹر، اور متن ساتھ</h2>\n<p>فلٹر تصویر کا کنٹراسٹ بدلتے ہیں، جو اس پر متن کو متاثر کرتا ہے۔ زیادہ کنٹراسٹ فلٹر پس منظر کو مصروف بنا سکتا ہے، جو پڑھنے کی اہلیت کو نقصان پہنچاتا ہے۔</p>\n<p>پہلے فلٹر لگائیں، پھر متن کنٹراسٹ چیک کریں۔ تصویر تاریک کرنے والا فلٹر سفید متن کو بہتر کر سکتا ہے، جبکہ اسے روشن کرنے والا اسی متن کو خراب کر سکتا ہے۔</p>\n<p>متن بھاری گرافکس کے لیے ہلکا فلٹر یا کوئی فلٹر نہ استعمال کریں۔ مضبوط متن کنٹراسٹ والی صاف تصویر ناقابل پڑھ الفاظ والی بہت فلٹر شدہ تصویر کو ہراتی ہے۔</p>\n<p>جب فلٹر اور متن کو ساتھ رہنا ہو تو متن کے پیچھے پینل بڑھائیں۔ پینل وہ مستقل پس منظر بحال کرتا ہے جو فلٹر نے لے لیا تھا۔</p>\n<h2 id=\"before-after-examples\">پہلے اور بعد: اچھا کنٹراسٹ کیسا لگتا ہے</h2>\n<p>بغیر خاکہ کے روشن آسمان پر سفید متن والی تصویر کلاسک ناکامی ہے۔ الفاظ پوشیدہ ہوتے ہیں، اور دیکھنے والا صرف تصویر دیکھتا ہے۔</p>\n<p>تاریک اوورلے والی وہی تصویر فوراً پڑھنے کے قابل ہو جاتی ہے۔ آسمان تاریک ہوتا ہے، سفید حروف نمایاں ہوتے ہیں، اور تصویر پھر بھی اوورلے سے نظر آتی ہے۔</p>\n<p>مصروف ہجوم پر کیپشن جس کے پیچھے پینل ہو قابل اعتماد حل ہے۔ پینل صاف زون بناتا ہے، اور الفاظ پوری تصویر چھپائے بغیر پڑھنے کے قابل ہوتے ہیں۔</p>\n<p>اپنے کام کا ان مثالوں سے موازنہ کریں۔ اگر آپ کا متن ناکامیوں جیسا لگے تو خاکہ، سایہ، پینل، یا تاریک کرنے کا قدم بڑھائیں، اور دوبارہ چیک کریں۔</p>\n<h2 id=\"readability-checklist\">شائع کرنے سے پہلے پڑھنے کی اہلیت چیک لسٹ</h2>\n<p>متن کی پوری سطر پر کنٹراسٹ چیک کریں۔ ہر لفظ پڑھنے کے قابل ہونا چاہیے، صرف پہلے چند نہیں، اور پس منظر سطر کے نیچے نہیں بدلنا چاہیے۔</p>\n<p>فون پر فیڈ پیش نظارہ میں سائز چیک کریں۔ اگر الفاظ بغیر زوم کے پڑھنا مشکل ہوں تو سائز بڑھائیں یا متن مختصر کریں۔</p>\n<p>روشن سورج کی روشنی میں متن چیک کریں۔ اندر پڑھنے کے قابل کیپشن باہر ناکام ہو سکتا ہے، جہاں اسکرین مدھم حروف کو دھو دیتی ہے۔</p>\n<p>جگہ چیک کریں۔ متن سادہ علاقے پر، چہروں اور کناروں سے دور، اس کے گرد سانس لینے کے لیے کافی جگہ کے ساتھ بیٹھنا چاہیے۔</p>\n<p>عملی مراحل کے لیے <a href=\"/ur/blog/tasveer-ka-contrast-kaise-badlein/\">How to Adjust Image Contrast</a> اور <a href=\"/ur/blog/tasveer-par-text-kaise-likhein/\">How to Add Text to an Image</a> دیکھیں۔ مکمل گائیڈ کے لیے <a href=\"/ur/blog/tasveer-contrast-editor-rehnumai/\">Image Contrast Editor: Complete Guide</a> اور <a href=\"/ur/blog/tasveer-par-text-readability-tips/\">Text on Images: Fonts, Contrast and Readability</a> پڑھیں۔</p>\n";

